import pandas as pd
from pymatgen.core import Structure
import numpy as np

df = pd.read_csv('nlo_pool.csv').set_index('candidate_id')

def bond_stats(cid, pairs, rcut):
    s = Structure.from_str(df.loc[cid,'poscar'], fmt='poscar')
    counts = {p: [] for p in pairs}
    for i, site in enumerate(s):
        nbs = s.get_neighbors(site, rcut)
        for n in nbs:
            key = tuple(sorted([site.species_string, n.species_string]))
            if key in counts:
                # count each bond once
                if i < n.index:
                    d = np.linalg.norm(n.coords - site.coords)
                    counts[key].append(d)
    print(f"\n{cid} {df.loc[cid,'formula']} V={s.volume:.1f}")
    tot_beta = 0
    for k, ds in counts.items():
        if not ds: continue
        # simple β sum ~ alpha * N / d^2
        print(f"  {k[0]}-{k[1]}: N={len(ds)} d={min(ds):.3f}-{max(ds):.3f} mean={np.mean(ds):.3f} N/V={len(ds)/s.volume:.4f}")

for cid in ['c094','c097','c098','c014','c018','c016','c076','c077','c050','c037','c001']:
    s = Structure.from_str(df.loc[cid,'poscar'], fmt='poscar')
    elems = {e.symbol for e in s.composition.elements}
    if 'Se' in elems:
        pairs = {tuple(sorted([a,'Se'])) for a in elems if a!='Se'}
        bond_stats(cid, pairs, 3.0)
    elif 'S' in elems:
        pairs = {tuple(sorted([a,'S'])) for a in elems if a!='S'}
        bond_stats(cid, pairs, 2.8)
